import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Identify strong candidates using t-statistics
    strong_candidates = []
    for i, fid in enumerate(feats.ids):
        # The types array contains the t-statistics for each feature
        t_stat = feats.types[i]
        if abs(t_stat) > 3.0:
            strong_candidates.append((fid, t_stat))

    # Sort by absolute t-statistic
    strong_candidates.sort(key=lambda x: abs(x[1]), reverse=True)

    # Remove near-duplicates based on correlation
    keep = set()
    corr_matrix = np.corrcoef(feats.x.T)
    for i, (fid1, _) in enumerate(strong_candidates):
        if fid1 in keep:
            continue
        keep.add(fid1)
        for j, (fid2, _) in enumerate(strong_candidates[i+1:], i+1):
            if abs(corr_matrix[feats.column(fid1), feats.column(fid2)]) >= 0.6 and fid2 in keep:
                # Keep the one with higher t-stat
                if abs(strong_candidates[i][1]) > abs(strong_candidates[j][1]):
                    keep.remove(fid2)
                else:
                    keep.remove(fid1)
                    break

    # Select top candidates as drivers
    drivers = tuple([fid for fid, _ in strong_candidates if fid in keep][:MAX_DRIVERS])

    # For columns, use all features with strong associations
    columns = []
    for i, fid in enumerate(feats.ids):
        t_stat = feats.types[i]
        if abs(t_stat) > 2.0:
            columns.append(fid)

    # Remove near-duplicates from columns
    col_set = set(columns)
    for i, fid1 in enumerate(columns):
        for j, fid2 in enumerate(columns[i+1:], i+1):
            if abs(corr_matrix[feats.column(fid1), feats.column(fid2)]) >= 0.6:
                if abs(feats.types[feats.column(fid1)]) >= abs(feats.types[feats.column(fid2)]):
                    col_set.discard(fid2)
                else:
                    col_set.discard(fid1)
                    break

    columns = tuple(col_set)

    # Create products for highly correlated pairs
    products = []
    for i, fid1 in enumerate(columns):
        for j, fid2 in enumerate(columns[i+1:], i+1):
            if abs(corr_matrix[feats.column(fid1), feats.column(fid2)]) >= 0.6:
                products.append((fid1, fid2))

    # Create loadings for weighted score
    loadings = {}
    for fid in columns:
        loadings[fid] = feats.types[feats.column(fid)]

    return Design(drivers=drivers, columns=columns, products=products, loadings=loadings)
